import { Component, OnInit } from '@angular/core';
import { MisComprasService } from '../services/mis-compras.service';
@Component({
  selector: 'app-productos-destacados',
  templateUrl: './productos-destacados.component.html',
  styleUrls: ['./productos-destacados.component.css']
})
export class ProductosDestacadosComponent implements OnInit{

  public primerProducto: any;
  public ultimoProducto: any;

  //defines constructor
  constructor(private misComprasService: MisComprasService){} //le pasas lo que vas a necesitar para incializarlo

  ngOnInit(): void { //inicializas el nuevo componente para que funcione
     
     this.misComprasService.misComprasSeleccionadas$.subscribe(compras => {

      if(compras.length > 0){ //si las compras son mayores de 0

        const primerPedido = compras[0];  //recogemos el primer pedido
        const ultimoPedido = compras[compras.length-1];  //recogemos el ultimo pedido

        //AHORA DE EL PRIMER PEDIDO TIENES QUE SACAR EL PRIMER PRODUCTO Y DEL ULTIMO PEDIDO SACAR SU ULTIMO PRODUCTO
        this.primerProducto = primerPedido.productos[0];  // -> sacamos el primer producto del primer pedido
        this.ultimoProducto = ultimoPedido.productos[ultimoPedido.productos.length -1];  // -> sacamos el ultimo producto del ultimo pedido

      }

     });
      
  }
}
